import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

// Load font at module level to prevent flicker
const { fontFamily: spaceGrotesk } = loadSpaceGrotesk();



export type MathBreakdownProps = Record<string, any>;

const MathBreakdown: React.FC<MathBreakdownProps> = ({
  backgroundColor = "#020617",
  transparentBackground = false,
  durationInSeconds = 8,
  titleText = "Scenario 1",
  priceAmount = 50,
  cpaAmount = 25,
  cogsAmount = 13,
  textColor = "#F8FAFC",
  cpaGlowColor = "#0EA5E9",
  profitColor = "#22C55E",
  lineColor = "#334155",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Responsive calculations
  const s = Math.min(width, height);
  const titleFontSize = s * 0.07;
  const mathFontSize = s * 0.08;
  const labelFontSize = s * 0.04;
  const rowSpacing = s * 0.04;

  // Derived values
  const profitAmount = priceAmount - cpaAmount - cogsAmount;

  // Animation Timings (staggered entrance)
  const getEntryAnim = (delayFrames: number) => {
    const entryFrame = Math.max(0, frame - delayFrames);
    const opacity = interpolate(entryFrame, [0, 15], [0, 1], {
      extrapolateRight: "clamp",
    });
    const yOffset = interpolate(entryFrame, [0, 15], [40, 0], {
      extrapolateRight: "clamp",
    });
    const scale = spring({
      fps,
      frame: entryFrame,
      config: { damping: 14, mass: 0.8 },
    });
    return { opacity, yOffset, scale };
  };

  const titleAnim = getEntryAnim(0);
  const priceAnim = getEntryAnim(15);
  const cpaAnim = getEntryAnim(35);
  const cogsAnim = getEntryAnim(55);
  const lineAnim = getEntryAnim(70);
  const profitAnim = getEntryAnim(85);

  // Dynamic Glow for CPA
  const glowPulse = interpolate(
    Math.sin(frame * 0.1),
    [-1, 1],
    [0.7, 1.2]
  );
  const cpaGlowStyle = {
    color: textColor,
    textShadow: `0 0 ${10 * glowPulse}px ${cpaGlowColor}, 0 0 ${
      25 * glowPulse
    }px ${cpaGlowColor}, 0 0 ${40 * glowPulse}px ${cpaGlowColor}`,
    transition: "none",
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: spaceGrotesk,
        color: textColor,
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: "center",
        padding: "10%",
      }}
    >
      {/* Title */}
      <div
        style={{
          fontSize: titleFontSize,
          fontWeight: 700,
          marginBottom: s * 0.1,
          opacity: titleAnim.opacity,
          transform: `translateY(${titleAnim.yOffset}px) scale(${titleAnim.scale})`,
          textAlign: "center",
          letterSpacing: "-0.02em",
          transition: "none",
        }}
      >
        {titleText}
      </div>

      {/* Math Container */}
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: rowSpacing,
          width: "90%",
          maxWidth: 900,
        }}
      >
        {/* Row 1: Price */}
        <div
          style={{
            display: "flex",
            alignItems: "baseline",
            opacity: priceAnim.opacity,
            transform: `translateY(${priceAnim.yOffset}px)`,
            transition: "none",
          }}
        >
          <div style={{ width: "15%", textAlign: "right" }} />
          <div
            style={{
              width: "40%",
              textAlign: "right",
              fontSize: mathFontSize,
              fontWeight: 600,
            }}
          >
            ${priceAmount}
          </div>
          <div
            style={{
              width: "45%",
              paddingLeft: s * 0.03,
              fontSize: labelFontSize,
              opacity: 0.7,
            }}
          >
            (Price)
          </div>
        </div>

        {/* Row 2: CPA (Glowing) */}
        <div
          style={{
            display: "flex",
            alignItems: "baseline",
            opacity: cpaAnim.opacity,
            transform: `translateY(${cpaAnim.yOffset}px) scale(${cpaAnim.scale})`,
            transition: "none",
          }}
        >
          <div
            style={{
              width: "15%",
              textAlign: "right",
              fontSize: mathFontSize,
              fontWeight: 600,
              ...cpaGlowStyle,
            }}
          >
            -
          </div>
          <div
            style={{
              width: "40%",
              textAlign: "right",
              fontSize: mathFontSize,
              fontWeight: 600,
              ...cpaGlowStyle,
            }}
          >
            ${cpaAmount}
          </div>
          <div
            style={{
              width: "45%",
              paddingLeft: s * 0.03,
              fontSize: labelFontSize,
              fontWeight: 500,
              ...cpaGlowStyle,
            }}
          >
            (CPA)
          </div>
        </div>

        {/* Row 3: COGS */}
        <div
          style={{
            display: "flex",
            alignItems: "baseline",
            opacity: cogsAnim.opacity,
            transform: `translateY(${cogsAnim.yOffset}px)`,
            transition: "none",
          }}
        >
          <div
            style={{
              width: "15%",
              textAlign: "right",
              fontSize: mathFontSize,
              fontWeight: 600,
            }}
          >
            -
          </div>
          <div
            style={{
              width: "40%",
              textAlign: "right",
              fontSize: mathFontSize,
              fontWeight: 600,
            }}
          >
            ${cogsAmount}
          </div>
          <div
            style={{
              width: "45%",
              paddingLeft: s * 0.03,
              fontSize: labelFontSize,
              opacity: 0.7,
            }}
          >
            (COGS)
          </div>
        </div>

        {/* Divider Line */}
        <div
          style={{
            height: s * 0.005,
            backgroundColor: lineColor,
            width: `${lineAnim.opacity * 100}%`,
            alignSelf: "center",
            marginTop: s * 0.02,
            marginBottom: s * 0.02,
            borderRadius: s * 0.01,
            transition: "none",
          }}
        />

        {/* Row 4: Profit */}
        <div
          style={{
            display: "flex",
            alignItems: "baseline",
            opacity: profitAnim.opacity,
            transform: `translateY(${profitAnim.yOffset}px) scale(${profitAnim.scale})`,
            color: profitColor,
            transition: "none",
          }}
        >
          <div
            style={{
              width: "15%",
              textAlign: "right",
              fontSize: mathFontSize,
              fontWeight: 700,
            }}
          >
            =
          </div>
          <div
            style={{
              width: "40%",
              textAlign: "right",
              fontSize: mathFontSize * 1.1,
              fontWeight: 700,
            }}
          >
            ${profitAmount}
          </div>
          <div
            style={{
              width: "45%",
              paddingLeft: s * 0.03,
              fontSize: labelFontSize,
              fontWeight: 600,
            }}
          >
            (Profit)
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default MathBreakdown;